def icon(name, size=20, cls='', stroke=2):
    """Lucide アイコンを <svg> として返す。

    size   … 1辺の画素数
    cls    … 追加の class（既定の "lc" は必ず付く＝縦位置合わせ用）
    stroke … 線の太さ。小さく使うときは太め、大きく使うときは細めが読みやすい
    """
    try:
        body = _PATHS[name]
    except KeyError:
        raise KeyError(
            'そのアイコンはありません: %r。使えるのは: %s'
            % (name, ', '.join(sorted(_PATHS)))) from None
    c = ('lc ' + cls).strip()
    return (
        '<svg class="%s" xmlns="http://www.w3.org/2000/svg" width="%s" height="%s" '
        'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="%s" '
        'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" '
        'focusable="false">%s</svg>' % (c, size, size, stroke, body))


def names():
    """登録済みのアイコン名（テストが使う）"""
    return set(_PATHS)
